/// あるrunの状態ログ。nodeごとの、collectorが保存したstdoutのlog。
pub struct Source {
    pub node: String,
    pub path: PathBuf,
}

pub fn collector_names(collectors: &[crate::config::CollectorConfig]) -> BTreeSet<String> {
    collectors
        .iter()
        .filter(|collector| {
            matches!(
                collector.parser,
                Some(crate::config::CollectorParser::StateLog)
            )
        })
        .map(|collector| collector.name.clone())
        .chain(std::iter::once(DELTA_COLLECTOR.into()))
        .collect()
}

/// `collectors`は`parser = "state-log"`のcollectorの名前（設定が無いときは[`DELTA_COLLECTOR`]）。
pub fn sources(
    manifest: &crate::model::RunManifest,
    logs_dir: &Path,
    collectors: &BTreeSet<String>,
) -> Vec<Source> {
    manifest
        .logs
        .iter()
        .filter(|log| {
            log.kind
                .strip_prefix("collector:")
                .and_then(|rest| rest.strip_suffix(":stdout"))
                .is_some_and(|name| collectors.contains(name))
        })
        .map(|log| Source {
            node: log.node.clone().unwrap_or_else(|| "local".into()),
            path: logs_dir.join(format!("{}.zst", log.id)),
        })
        .filter(|source| source.path.is_file())
        .collect()
}

