CREATE TABLE state_events (
  node TEXT NOT NULL,
  t INTEGER NOT NULL,          -- Unix時刻のマイクロ秒
  at TEXT NOT NULL,            -- tをRFC 3339（UTC、マイクロ秒）にしたもの
