use crate::Error;

#[derive(Debug, thiserror::Error)]
pub enum PaymentGatewayError {
    #[error("reqwest error: {0}")]
    Reqwest(#[from] reqwest::Error),
    #[error("[POST /payments] failed: {0}")]
    Failed(String),
}

#[derive(Debug, serde::Serialize)]
pub struct PaymentGatewayPostPaymentRequest {
    pub amount: i32,
}

fn http_client() -> &'static reqwest::Client {
    static CLIENT: std::sync::OnceLock<reqwest::Client> = std::sync::OnceLock::new();
    CLIENT.get_or_init(reqwest::Client::new)
}

/// 決済を1回だけ行う。同じライドの決済は`idempotency_key`（ライドID）で冪等になるので、
/// 失敗（204以外、通信の失敗）は同じkeyで送り直す。409は同じkeyの決済が実行中という意味で、
/// 終わるのを待って送り直す。元は失敗のたびに`GET /payments`で件数を比べ、100ms待っていた。
pub async fn request_payment_gateway_post_payment(
    payment_gateway_url: &str,
    token: &str,
    param: &PaymentGatewayPostPaymentRequest,
    idempotency_key: &str,
) -> Result<(), Error> {
    let mut retry = 0;
    loop {
        let result = http_client()
            .post(format!("{payment_gateway_url}/payments"))
            .bearer_auth(token)
            .header("Idempotency-Key", idempotency_key)
            .json(param)
            .send()
            .await;
        let failure = match result {
            Ok(res) if res.status() == reqwest::StatusCode::NO_CONTENT => return Ok(()),
            Ok(res) => format!("status {}", res.status()),
            Err(e) => e.to_string(),
        };
        if retry >= PAYMENT_RETRIES {
            return Err(Error::PaymentGateway(PaymentGatewayError::Failed(failure)));
        }
        retry += 1;
        tracing::warn!("payment retry {retry} for {idempotency_key}: {failure}");
        tokio::time::sleep(PAYMENT_RETRY_WAIT).await;
    }
}

/// 送り直す回数の上限と間隔（評価のタイムアウトは10秒）。
const PAYMENT_RETRIES: u32 = 50;
const PAYMENT_RETRY_WAIT: std::time::Duration = std::time::Duration::from_millis(20);

use axum::extract::State;
use axum::http::StatusCode;

use crate::{AppState, Error};

pub fn internal_routes() -> axum::Router<AppState> {
    axum::Router::new().route(
        "/api/internal/matching",
        axum::routing::get(internal_get_matching),
    )
}

// このAPIをインスタンス内から一定間隔で叩かせることで、椅子とライドをマッチングさせる
async fn internal_get_matching(
    State(AppState { store }): State<AppState>,
) -> Result<StatusCode, Error> {
    // 待っているライドを古い順に、乗車位置へ最も早く着く空き椅子（距離÷速度）へ割り当てる。
    // 同じ椅子を2つのライドへ割り当てないよう、マッチングは同時に1つだけ動かす（store）
    store.matching().await?;

    Ok(StatusCode::NO_CONTENT)
}
