async fn app_get_notification(
    State(AppState { store }): State<AppState>,
    headers: axum::http::HeaderMap,
    axum::Extension(user): axum::Extension<User>,
) -> Result<axum::response::Response, Error> {
    use axum::response::IntoResponse as _;
    if crate::wants_json(&headers) {
        let data = app_notification(&store, &user).await?.map(|(data, _)| data);
        return Ok(axum::Json(AppGetNotificationResponse {
            data,
            retry_after_ms: Some(APP_NOTIFICATION_RETRY_MS),
        })
        .into_response());
    }
    let id = user.id.clone();
    Ok(crate::notification_sse(store, &id, move |store| {
        let user = user.clone();
        async move { app_notification(&store, &user).await }
    }))
}

/// 利用者へ通知する中身（まだ通知していない最古の状態、無ければ最新の状態）と、未通知の状態を
/// 今通知したか。ライドが無ければNone。
async fn app_notification(
    store: &crate::store::Store,
    user: &User,
) -> Result<Option<(AppGetNotificationResponseData, bool)>, Error> {
    let (data, yet_sent) = {
        let d = store.read();
        let Some(ride) = d.latest_ride_of_user(&user.id) else {
            return Ok(None);
        };

        // まだ通知していない最古の状態、無ければ最新の状態
        let yet_sent = ride.statuses.iter().position(|s| s.app_sent_at.is_none());
        let status = match yet_sent {
            Some(i) => ride.statuses[i].status,
            None => ride.latest_status().ok_or(sqlx::Error::RowNotFound)?,
        };

        let chair = match &ride.ride.chair_id {
            Some(chair_id) => {
                let chair = d.chairs.get(chair_id).ok_or(sqlx::Error::RowNotFound)?;
                // ARRIVED・CARRYING・COMPLETEDをすべて経たライドの数と評価の平均
                let (total_rides_count, total_evaluation_avg) = chair.stats();
                Some(AppGetNotificationResponseChair {
                    id: chair.chair.id.clone(),
                    name: chair.chair.name.clone(),
                    model: chair.chair.model.clone(),
                    stats: AppGetNotificationResponseChairStats {
                        total_rides_count,
                        total_evaluation_avg,
                    },
                })
            }
            None => None,
        };

        let data = AppGetNotificationResponseData {
            ride_id: ride.ride.id.clone(),
            pickup_coordinate: Coordinate {
                latitude: ride.ride.pickup_latitude,
                longitude: ride.ride.pickup_longitude,
            },
            destination_coordinate: Coordinate {
                latitude: ride.ride.destination_latitude,
                longitude: ride.ride.destination_longitude,
            },
            fare: ride.fare(),
            status: status.as_str().to_owned(),
            chair,
            created_at: ride.ride.created_at.timestamp_millis(),
            updated_at: ride.ride.updated_at.timestamp_millis(),
        };
        // 前に通知した状態（未通知の最古より前はすべて通知済み）
        let yet_sent = yet_sent.map(|i| {
            (
                ride.ride.id.clone(),
                ride.statuses[i].id.clone(),
                i.checked_sub(1).map(|p| ride.statuses[p].status),
                status,
            )
        });
        (data, yet_sent)
    };

    let sent = yet_sent.is_some();
    if let Some((ride_id, status_id, previous, status)) = yet_sent {
        store
            .mark_app_sent(&ride_id, &status_id, previous, status, &user.id)
            .await?;
    }

    Ok(Some((data, sent)))
}

