async fn app_get_nearby_chairs(
    State(AppState { store }): State<AppState>,
    Query(query): Query<AppGetNearbyChairsQuery>,
) -> Result<axum::Json<AppGetNearbyChairsResponse>, Error> {
    let distance = query.distance.unwrap_or(50);
    let coordinate = Coordinate {
        latitude: query.latitude,
        longitude: query.longitude,
    };

    // retrieved_atは秒に切り捨てて返すので、その秒より後に空いた椅子はベンチからはまだライド中に見える。
    // 椅子がCOMPLETEDを受け取った直後もベンチ側の反映が遅れるので（49344acb: 空いて32-35ms後に
    // CODE=30が24件）、直近300msに空いた椅子も返さない。1秒前まで広げると椅子が見えない時間が
    // 延びて得点が下がった（afb88aa3、-6%）
    let retrieved_at = chrono::Utc::now();
    let retrieved_second = chrono::DateTime::from_timestamp(retrieved_at.timestamp(), 0)
        .unwrap()
        .min(retrieved_at - chrono::TimeDelta::milliseconds(300));
    let mut nearby_chairs = Vec::new();
    {
        let d = store.read();
        // 椅子のID順（元の`SELECT * FROM chairs`の順）
        for chair in d.chairs.values() {
            if !chair.chair.is_active {
                continue;
            }

            // 過去にライドが存在し、かつ、それが完了していない椅子は除く。
            // 完了しても椅子がCOMPLETEDの通知を受け取るまではライド中と見られる（CODE=30、1e9b0e4f）
            if chair.unfinished > 0 || !d.chair_free_for_matching(&chair.chair.id) {
                continue;
            }
            let freed_at = d
                .latest_ride_of_chair(&chair.chair.id)
                .and_then(|r| r.statuses.last())
                .and_then(|s| s.chair_sent_at);
            if freed_at.is_some_and(|t| t >= retrieved_second) {
                continue;
            }

            // 最新の位置情報
            let Some(chair_location) = chair.location else {
                continue;
            };
            if crate::calculate_distance(
                coordinate.latitude,
                coordinate.longitude,
                chair_location.latitude,
                chair_location.longitude,
            ) <= distance
            {
                nearby_chairs.push(AppGetNearbyChairsResponseChair {
                    id: chair.chair.id.clone(),
                    name: chair.chair.name.clone(),
                    model: chair.chair.model.clone(),
                    current_coordinate: Coordinate {
                        latitude: chair_location.latitude,
                        longitude: chair_location.longitude,
                    },
                });
            }
        }
    }

    // 近くに空き椅子が無いと、利用者は椅子が見えるまでこのAPIとGET /api/app/ridesを繰り返す
    // （survey-run 90f3b115: 1ライドあたり約4.9回、計15万回）。ベンチの機械は負荷が上がるほど遅く
    // なる（決済の再試行の間隔が52→158ms、bc777727）ので、空の応答だけ少し待たせて空振りの回数を
    // 減らす。椅子が見える応答は待たせない
    if nearby_chairs.is_empty() {
        let delay = nearby_empty_delay();
        if !delay.is_zero() {
            tokio::time::sleep(delay).await;
        }
    }

    Ok(axum::Json(AppGetNearbyChairsResponse {
        chairs: nearby_chairs,
        retrieved_at: retrieved_at.timestamp(),
    }))
}

/// 空の`nearby-chairs`を返す前に待つ時間（`ISUCON_NEARBY_EMPTY_DELAY_MS`、既定100ms）。
fn nearby_empty_delay() -> std::time::Duration {
    static DELAY: std::sync::OnceLock<std::time::Duration> = std::sync::OnceLock::new();
    *DELAY.get_or_init(|| {
        let ms = std::env::var("ISUCON_NEARBY_EMPTY_DELAY_MS")
            .ok()
            .and_then(|v| v.parse().ok())
            .unwrap_or(100);
        std::time::Duration::from_millis(ms)
    })
}
use axum::{http::StatusCode, response::Response};

/// handlerはDBへ直接触れず、読み取りも書き込みも`store`を通す（`store.rs`）。
#[derive(Clone)]
pub struct AppState {
    pub store: std::sync::Arc<store::Store>,
}

/// initialize以外のリクエストを、initializeの読み込みが終わるまで待たせる。
pub async fn gate_middleware(
    axum::extract::State(AppState { store }): axum::extract::State<AppState>,
    req: axum::extract::Request,
    next: axum::middleware::Next,
) -> Response {
    let _open = store.enter().await;
    next.run(req).await
}

/// 通知を`application/json`で求められたときだけ、従来のpolling（JSON）で返す。それ以外は
/// SSE（クライアントはContent-Typeで方式を決める。公式のクライアントはAcceptを付けない）。
pub fn wants_json(headers: &axum::http::HeaderMap) -> bool {
    headers
        .get(axum::http::header::ACCEPT)
        .and_then(|v| v.to_str().ok())
        .is_some_and(|v| v.contains("application/json"))
}

/// 通知のSSE。`next`は通知する中身と、未通知の状態を今通知したか（`mark_*_sent`した）を返す。
/// 接続した直後に最新の状態を送り、その後は未通知の状態があるたびに送る。送るものが無ければ、
/// `id`（利用者・椅子）の中身が変わるまで待つ。
pub fn notification_sse<T, F, Fut>(store: std::sync::Arc<store::Store>, id: &str, next: F) -> Response
where
    T: serde::Serialize + Send + 'static,
    F: Fn(std::sync::Arc<store::Store>) -> Fut + Send + Sync + 'static,
    Fut: std::future::Future<Output = Result<Option<(T, bool)>, Error>> + Send,
{
    use axum::response::sse::{Event, Sse};
    use axum::response::IntoResponse as _;

    let rx = store.subscribe(id);
    let stream = futures_util::stream::unfold((store, rx, next, true), |(store, mut rx, next, first)| async move {
        loop {
            // 読む前に見た版を進める（読んでいる間の変化は次のchangedで拾う）
            rx.borrow_and_update();
            match next(store.clone()).await {
                Ok(Some((data, sent))) if first || sent => {
                    let event = Event::default().json_data(&data).unwrap_or_default();
                    return Some((Ok::<_, std::convert::Infallible>(event), (store, rx, next, false)));
                }
                Ok(_) => {}
                Err(e) => tracing::error!("notification: {e}"),
            }
            if rx.changed().await.is_err() {
                return None;
            }
        }
    });
    ([("x-accel-buffering", "no")], Sse::new(stream)).into_response()
}

#[derive(Debug, thiserror::Error)]
pub enum Error {
    #[error("I/O error: {0}")]
    Io(#[from] std::io::Error),
    #[error("SQLx error: {0}")]
    Sqlx(#[from] sqlx::Error),
    #[error("failed to initialize: stdout={stdout} stderr={stderr}")]
    Initialize { stdout: String, stderr: String },
    #[error("{0}")]
    PaymentGateway(#[from] crate::payment_gateway::PaymentGatewayError),
    #[error("{0}")]
    BadRequest(&'static str),
    #[error("{0}")]
    Unauthorized(&'static str),
    #[error("{0}")]
    NotFound(&'static str),
    #[error("{0}")]
    Conflict(&'static str),
}
impl axum::response::IntoResponse for Error {
    fn into_response(self) -> Response {
        let status = match self {
            Self::BadRequest(_) => StatusCode::BAD_REQUEST,
            Self::Unauthorized(_) => StatusCode::UNAUTHORIZED,
            Self::NotFound(_) => StatusCode::NOT_FOUND,
            Self::Conflict(_) => StatusCode::CONFLICT,
            Self::PaymentGateway(_) => StatusCode::BAD_GATEWAY,
            _ => StatusCode::INTERNAL_SERVER_ERROR,
        };

        #[derive(Debug, serde::Serialize)]
        struct ErrorBody {
            message: String,
        }
        let message = self.to_string();
        tracing::error!("{message}");

        (status, axum::Json(ErrorBody { message })).into_response()
    }
}

