/// matchingで遠いと見なす迎車距離（`Data::plan_matching`）。
const FAR_PICKUP: i32 = 200;
/// これより短く待っているライドは、近い（椅子, ライド）の組から割り当てる（`Data::plan_matching`）。
/// 長く待ったライドは古い順に優先する。
const NEAREST_RIDE_UNTIL: chrono::TimeDelta = chrono::TimeDelta::seconds(5);
/// 近い組から割り当てるときに並べる組の数の上限（待ちライド数×空き椅子数）。
const NEAREST_PAIRS_MAX: usize = 100_000;
/// 遠い椅子・位置の無い椅子を使うまでにライドを待たせる時間。
const FAR_PICKUP_AFTER: chrono::TimeDelta = chrono::TimeDelta::seconds(10);

/// WAL（書き込みの記録）。メモリを変える書き込みはすべてこの形で`Wal`へ1行ずつ追記してから
/// メモリへ反映し、再起動時は`load`（最後のinitializeの後のDB）の上に先頭から再生する。
/// DBへは書かない（読むのは起動時とinitializeだけ）。時刻はマイクロ秒。
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
#[serde(tag = "t")]
pub enum Record {
    Owner { id: String, name: String, access_token: String, chair_register_token: String, at: i64 },
    Chair { id: String, owner_id: String, name: String, model: String, access_token: String, at: i64 },
    Activity { chair_id: String, is_active: bool, at: i64 },
/// matchingの入力（`Data::matching_input`）。空き椅子は(ID, 速度, 位置)、待っているライドは
/// 作成順の(作成時刻, ID, 乗車位置)。
pub struct MatchingInput {
    now: DateTime<Utc>,
    free: Vec<(String, i32, Option<(i32, i32)>)>,
    rides: Vec<(DateTime<Utc>, String, (i32, i32))>,
}

impl MatchingInput {
    /// 割り当て（ライドID, 椅子ID）。長く待ったライドは古い順に先に取り、残りは早く着く組から取る。
    pub fn plan(self) -> Vec<(String, String)> {
        let MatchingInput { now, mut free, rides } = self;
        if rides.is_empty() || free.is_empty() {
            return Vec::new();
        }
        // 乗車位置への到着の早さ（小さいほど早い）。遠い椅子・位置の無い椅子は待たせたライドにだけ
        let arrival = |&(created_at, _, (plat, plon)): &(DateTime<Utc>, String, (i32, i32)),
                       &(_, speed, location): &(String, i32, Option<(i32, i32)>)| {
            let far_allowed = now - created_at >= FAR_PICKUP_AFTER;
            match location {
                Some((lat, lon)) => {
                    let distance = (lat - plat).abs() + (lon - plon).abs();
                    if distance > FAR_PICKUP && !far_allowed {
                        return None;
                    }
                    Some((0, (distance + speed - 1) / speed))
                }
                None if far_allowed => Some((1, 0)),
                None => None,
            }
        };
        let mut assignments = Vec::new();
        // 1. `NEAREST_RIDE_UNTIL`より長く待ったライドは、古い順に最も早く着く空き椅子へ。
        //    組が多すぎるときは、すべてのライドをこの順で割り当てる
        let pairs_fit = rides.len().saturating_mul(free.len()) <= NEAREST_PAIRS_MAX;
        let mut recent = Vec::new();
        for ride in &rides {
            if pairs_fit && now - ride.0 < NEAREST_RIDE_UNTIL {
                recent.push(ride);
                continue;
            }
            if free.is_empty() {
                continue;
            }
            // 近くに空き椅子が無ければ、このライドは次のmatchingまで待つ（後のライドは続けて探す）
            let Some((index, _)) = free
                .iter()
                .enumerate()
                .filter_map(|(index, chair)| Some((index, arrival(ride, chair)?)))
                .min_by_key(|&(_, key)| key)
            else {
                continue;
            };
            let (chair_id, _, _) = free.swap_remove(index);
            assignments.push((ride.1.clone(), chair_id));
        }
        // 2. 残りは、早く着く（椅子, ライド）の組から割り当てる。椅子が足りない間は、空いた椅子を
        //    近くで待つライドへ回して迎車を短くする（同じ早さなら古いライド、ID順で先の椅子）
        if !free.is_empty() && !recent.is_empty() {
            let mut pairs = Vec::new();
            for (r, ride) in recent.iter().enumerate() {
                for (c, chair) in free.iter().enumerate() {
                    if let Some(key) = arrival(ride, chair) {
                        pairs.push((key, r, c));
                    }
                }
            }
            pairs.sort_unstable();
            let mut ride_taken = vec![false; recent.len()];
            let mut chair_taken = vec![false; free.len()];
            for (_, r, c) in pairs {
                if ride_taken[r] || chair_taken[c] {
                    continue;
                }
                ride_taken[r] = true;
                chair_taken[c] = true;
                assignments.push((recent[r].1.clone(), free[c].0.clone()));
            }
        }
        assignments
    }
}

#[derive(Debug, Default)]
pub struct Data {
    pub payment_gateway_url: String,
    pub users: HashMap<String, UserRec>,
    pub user_by_token: HashMap<String, String>,
    pub user_by_invitation: HashMap<String, String>,
    /// `INV_<招待コード>`のクーポンの数（招待された人数）。
    pub invited: HashMap<String, usize>,
    pub payment_tokens: HashMap<String, String>,
    pub owners: HashMap<String, OwnerRec>,
