    }

    /// 椅子の最新のライド（`updated_at`が最も新しいもの）。
    pub fn latest_ride_of_chair(&self, chair_id: &str) -> Option<&RideRec> {
        self.rides
            .get(self.chairs.get(chair_id)?.latest_ride.as_ref()?)
    }

    /// matchingで空きと見なすか: 割り当てられたすべてのライドで、椅子へ通知した状態がちょうど6つ。
    pub fn chair_free_for_matching(&self, chair_id: &str) -> bool {
        // 毎回ライドと状態を数え直すと、nearby-chairs（3029e24cで7.5万回）とmatchingが全椅子×全ライド×
        // 6状態を数えてread lockを長く持った。割り当て・通知のたびに`unsent`を直す
        self.chairs.get(chair_id).is_none_or(|chair| chair.unsent == 0)
    }

    /// 椅子へ`status_id`の状態を通知したことを記録し、6つそろったら椅子の`unsent`を減らす。
    fn set_chair_sent(&mut self, ride_id: &str, status_id: &str, at: DateTime<Utc>) {
        let Some(ride) = self.rides.get_mut(ride_id) else {
            return;
        };
        let was_sent = ride.sent_to_chair();
        if let Some(s) = ride.statuses.iter_mut().find(|s| s.id == status_id) {
            s.chair_sent_at = Some(at);
        }
        if was_sent || !ride.sent_to_chair() {
            return;
        }
        if let Some(chair) = ride.ride.chair_id.as_ref().and_then(|id| self.chairs.get_mut(id)) {
            chair.unsent = chair.unsent.saturating_sub(1);
        }
    }

    /// matchingの割り当て（ライドID, 椅子ID）。受付中でモデルの速度が分かる空き椅子を、乗車位置へ
    /// 最も早く着く（距離÷速度の切り上げ）ように割り当てる。長く待ったライドは古い順に先に取り、
    /// 残りは早く着く組から取る（椅子が足りない間に迎車を短くする）。
    /// 位置の無い椅子は位置のある椅子より後に回す。同じ椅子は1回のmatchingで1度だけ使う。
    /// 迎車距離がこれを超える椅子は、ライドが`FAR_PICKUP_AFTER`待つまで使わない。地域（チェアタウン・
    /// コシカケシティ）は約300離れていて、地域の中の迎車は150未満、またぐ迎車は平均18秒かかった（966fec1a）。
    /// 位置の無い椅子も、どちらの地域にいるか分からないので同じ扱い。
    pub fn plan_matching(&self, now: DateTime<Utc>) -> Vec<(String, String)> {
        self.matching_input(now).plan()
    }

    /// matchingに要る値（空き椅子と待っているライド）の写し。read lockの中ではこれだけを作り、
    /// 組を並べる`MatchingInput::plan`はlockの外で行う（組は最大10万で、並べる間lockを持つと
    /// 書き込みとほかの読み取りが止まった）。
    pub fn matching_input(&self, now: DateTime<Utc>) -> MatchingInput {
        if self.unassigned.is_empty() {
            return MatchingInput { now, free: Vec::new(), rides: Vec::new() };
        }
        // 椅子のID順に並べる（同じ到着時間なら先に並んだ椅子）
        let free = self
            .chairs
            .values()
            .filter(|c| c.chair.is_active)
            .filter_map(|c| {
                let speed = *self.chair_speeds.get(&c.chair.model)?;
                Some((c.chair.id.clone(), speed.max(1), c.location.map(|l| (l.latitude, l.longitude))))
            })
            .filter(|(id, _, _)| self.chair_free_for_matching(id))
            .collect();
        let rides = self
            .unassigned
            .iter()
            .filter_map(|(created_at, ride_id)| {
                let ride = &self.rides.get(ride_id)?.ride;
                Some((*created_at, ride_id.clone(), (ride.pickup_latitude, ride.pickup_longitude)))
            })
            .collect();
        MatchingInput { now, free, rides }
    }

    fn insert_user(&mut self, rec: UserRec) {
        self.user_by_token
            .insert(rec.user.access_token.clone(), rec.user.id.clone());
        self.user_by_invitation
            .insert(rec.invitation_code.clone(), rec.user.id.clone());
        self.users.insert(rec.user.id.clone(), rec);
