fn json_string(line: &mut String, value: &str) {
    line.push('"');
    for character in value.chars() {
        match character {
            '"' => line.push_str("\\\""),
            '\\' => line.push_str("\\\\"),
            '\n' => line.push_str("\\n"),
            '\r' => line.push_str("\\r"),
            '\t' => line.push_str("\\t"),
            character if (character as u32) < 0x20 => {
                let _ = write!(line, "\\u{:04x}", character as u32);
            }
            character => line.push(character),
        }
    }
    line.push('"');
}

