    pub fn read(&self) -> RwLockReadGuard<'_, Data> {
        self.data.read().unwrap_or_else(|e| e.into_inner())
    }

    fn write(&self) -> RwLockWriteGuard<'_, Data> {
        self.data.write().unwrap_or_else(|e| e.into_inner())
    }

    /// 変更を確定する唯一の箇所。(1) DBへ書く（transactionならcommitまで）、(2) 成功したら
    /// メモリを変える、(3) 状態ログを書く。DBが失敗したらメモリも状態ログも変えない。
    async fn commit<T>(
        &self,
        write: impl Future<Output = sqlx::Result<()>>,
        log: Pending,
        apply: impl FnOnce(&mut Data) -> T,
    ) -> Result<T, Error> {
        write.await?;
        let (out, touched) = {
            let mut data = self.write();
            let out = apply(&mut data);
            (out, std::mem::take(&mut data.touched))
        };
        log.emit();
        self.wake(touched);
        Ok(out)
    }

    /// 書き込みを確定する箇所。(1) 一意制約を確かめ、(2) WALへ追記し、(3) メモリを変え、
    /// (4) 状態ログを書き、SSEの接続を起こす。(1)から(3)はDataのwrite lockの中で続けて行うので、
    /// WALの順とメモリへ反映した順は同じ。
    fn commit_record(&self, record: Record, log: Pending) -> Result<(), Error> {
        let touched = {
            let mut data = self.write();
            data.check(&record)?;
            self.wal.append(&record)?;
            data.apply(&record);
            std::mem::take(&mut data.touched)
        };
        log.emit();
        self.wake(touched);
        Ok(())
    }

    /// initialize以外のリクエストが通る門。initializeの読み込みが終わるまで待たせる。
    pub async fn matching(&self) -> Result<(), Error> {
        let Ok(_running) = self.matching.try_lock() else {
            return Ok(());
        };
        let input = self.read().matching_input(now());
        let assignments = input.plan();
        if assignments.is_empty() {
            return Ok(());
        }
        let mut log = Pending::new();
        for (ride_id, chair_id) in &assignments {
            log.changed("ride_assignment", ride_id, "UNASSIGNED", "ASSIGNED", &[("chair", chair_id.into())]);
        }
        self.commit_record(Record::Assign { pairs: assignments, at: micros(now()) }, log)?;
        Ok(())
    }
}

